-- V2026_09_15_01: Bahrain Visa domestic alignment to the Visa Domestic IRF Guide
-- (Bahrain Supplemental Requirements, effective 25 Jan 2025).
--
-- What this does:
--   A) Seeds ref_bin_product_tier with Visa product codes (A/F/P/... -> VCLAS/VGOLD/...).
--      Until now the table held only Mastercard codes, so every BH Visa txn fell
--      through to the flat 1.75/1.90 tier-wildcard default.
--   B) Inserts BH Visa product-tier rate rows at priority 20:
--      POS = manual Product Rate, ECOM = manual Alternative Rate (product +0.20%).
--      The existing priority-15 flat rows are KEPT as last resort for unmapped BINs;
--      sector MCC rows at priority 40/60 still win (ORDER BY priority DESC).
--   C) Fixes: MCC 8220 to Education 0.85%; auto dealers 5511/5521 cap at USD 150
--      (56.40 BHD at the 0.376 peg - engine caps in store base currency);
--      deletes the redundant per-MCC Visa rows that sat at the default 1.75/1.90.
--
-- Deliberate decisions (flagged for business sign-off):
--   * J3 (prepaid) priced as Classic - the manual has no prepaid product line.
--   * I1 (Infinite Privilege) priced as Infinite.
--   * Codes with no manual treatment (L Electron, Q private label, M, V, X, E, R)
--     are NOT seeded - they fall to the flat priority-15 fallback.
--   * Acquirer-downgrade ladder (+0.25%) not modeled - no downgrade signal in feed.
--
-- Guarded on schema_migration_log per the ledger convention: re-runs are no-ops.

-- ---------------------------------------------------------------------------
-- A) Visa product code -> tier seeds (shared table; 1-2 char Visa codes cannot
--    collide with 3-char MC codes). Tier labels <= 10 chars (card_tier limit).
-- ---------------------------------------------------------------------------
INSERT INTO ref_bin_product_tier (product_code, card_tier, card_class, note) SELECT 'A','VCLAS','CONSUMER','Visa Traditional -> Classic 1.25' WHERE NOT EXISTS (SELECT 1 FROM schema_migration_log WHERE filename='V2026_09_15_01__visa_bh_manual_align.sql') ON CONFLICT (product_code) DO NOTHING;
INSERT INTO ref_bin_product_tier (product_code, card_tier, card_class, note) SELECT 'F','VCLAS','CONSUMER','Visa Classic 1.25' WHERE NOT EXISTS (SELECT 1 FROM schema_migration_log WHERE filename='V2026_09_15_01__visa_bh_manual_align.sql') ON CONFLICT (product_code) DO NOTHING;
INSERT INTO ref_bin_product_tier (product_code, card_tier, card_class, note) SELECT 'J3','VCLAS','CONSUMER','Visa prepaid -> Classic treatment (no prepaid line in BH manual)' WHERE NOT EXISTS (SELECT 1 FROM schema_migration_log WHERE filename='V2026_09_15_01__visa_bh_manual_align.sql') ON CONFLICT (product_code) DO NOTHING;
INSERT INTO ref_bin_product_tier (product_code, card_tier, card_class, note) SELECT 'P','VGOLD','CONSUMER','Visa Gold 1.40' WHERE NOT EXISTS (SELECT 1 FROM schema_migration_log WHERE filename='V2026_09_15_01__visa_bh_manual_align.sql') ON CONFLICT (product_code) DO NOTHING;
INSERT INTO ref_bin_product_tier (product_code, card_tier, card_class, note) SELECT 'B','VRWD','CONSUMER','Visa Traditional Rewards -> Rewards 1.70' WHERE NOT EXISTS (SELECT 1 FROM schema_migration_log WHERE filename='V2026_09_15_01__visa_bh_manual_align.sql') ON CONFLICT (product_code) DO NOTHING;
