-- ---------------------------------------------------------------------------
-- B) BH Visa product-tier rate rows, priority 20 (beats the 15 flat fallback,
--    loses to sector MCC rows at 40/60 - matching the manual's hierarchy where
--    industry fee programs precede product rate). card_type stays NULL: the BH
--    manual prices by product regardless of funding source (F is 84% debit and
--    must still get Classic 1.25).
--    POS = Product Rate; ECOM = Alternative Rate (product +0.20).
-- ---------------------------------------------------------------------------
INSERT INTO interchange_rate_local (tenant_id,priority,dest,channel,scheme_group,card_type,tier,mcc_sector,interchange_pct,cap_amount,label,mcc,country_code,cap_currency_code,flat_fee,rate_status,effective_from,effective_to,source_note,min_ticket,max_ticket) SELECT NULL,20,'DOMESTIC','POS','Visa',NULL,'VCLAS',NULL,0.012500,NULL,'BH Visa Classic POS 1.25 (manual product rate)',NULL,'BH','BHD',0.0000,'APPROVED',NULL,NULL,'Visa BH IRF Guide 2025-01-25 s5.1',NULL,NULL WHERE NOT EXISTS (SELECT 1 FROM schema_migration_log WHERE filename='V2026_09_15_01__visa_bh_manual_align.sql');
