-- ---------------------------------------------------------------------------
-- C) Sector fixes + cleanup
-- ---------------------------------------------------------------------------
-- C1: MCC 8220 (colleges/universities) is Education 0.85% in the manual, was 0.75%.
UPDATE interchange_rate_local SET interchange_pct = 0.008500,
       label = 'BH Visa ' || channel || ' MCC 8220 (Education 0.85, fixed from 0.75)'
WHERE country_code='BH' AND scheme_group='Visa' AND mcc='8220' AND interchange_pct = 0.007500
  AND NOT EXISTS (SELECT 1 FROM schema_migration_log WHERE filename='V2026_09_15_01__visa_bh_manual_align.sql');

-- C2: Auto dealers 5511/5521 - manual caps consumer auto at USD 150.
--     Engine caps in store base currency (BHD): 150 USD * 0.376 = 56.40 BHD.
UPDATE interchange_rate_local SET cap_amount = 56.4000, cap_currency_code = 'BHD',
       label = label || ' cap USD150=56.40BHD'
WHERE country_code='BH' AND scheme_group='Visa' AND mcc IN ('5511','5521')
  AND interchange_pct = 0.012000 AND cap_amount IS NULL
  AND NOT EXISTS (SELECT 1 FROM schema_migration_log WHERE filename='V2026_09_15_01__visa_bh_manual_align.sql');

-- C3: Drop the redundant per-MCC Visa rows that sat at the flat default rate
--     (they added nothing over the priority-15 default and now would mask tiers
--     for those MCCs, since priority 60 beats the new tier rows at 20).
DELETE FROM interchange_rate_local
WHERE country_code='BH' AND scheme_group='Visa' AND priority=60 AND mcc IS NOT NULL
  AND interchange_pct IN (0.017500, 0.019000)
  AND NOT EXISTS (SELECT 1 FROM schema_migration_log WHERE filename='V2026_09_15_01__visa_bh_manual_align.sql');

-- Verify: expect 24 tier rows, 8220 at 0.85, 5511/5521 capped, 0 default-rate MCC rows
SELECT 'tier_rows' AS check, COUNT(*) FROM interchange_rate_local
WHERE country_code='BH' AND scheme_group='Visa' AND priority=20 AND tier LIKE 'V%'
UNION ALL
SELECT 'mcc8220_at_085', COUNT(*) FROM interchange_rate_local
WHERE country_code='BH' AND scheme_group='Visa' AND mcc='8220' AND interchange_pct=0.008500
UNION ALL
SELECT 'auto_capped', COUNT(*) FROM interchange_rate_local
WHERE country_code='BH' AND scheme_group='Visa' AND mcc IN ('5511','5521') AND cap_amount=56.4000
UNION ALL
SELECT 'redundant_left', COUNT(*) FROM interchange_rate_local
WHERE country_code='BH' AND scheme_group='Visa' AND priority=60 AND mcc IS NOT NULL
  AND interchange_pct IN (0.017500, 0.019000);

